// -----------------------------------------------------------------------------
// DeepInfra Implementation
// -----------------------------------------------------------------------------

use reqwest::Client;
use serde::Deserialize;

/// Client for Api.deepinfra.com
pub struct DeepInfraClient {
    client: Client,
    api_key: String,
}

impl DeepInfraClient {
    /// Create a new client from env var DEEPINFRA_API_TOKEN
    pub fn from_env() -> Result<Self, ModelError> {
        let api_key = std::env::var("DEEPINFRA_API_TOKEN")
            .map_err(|_| ModelError::Config("DEEPINFRA_API_TOKEN not set".to_string()))?;
        Ok(Self {
            client: Client::new(),
            api_key,
        })
    }
}

#[async_trait]
impl ModelClient for DeepInfraClient {
    fn name(&self) -> &str {
        "DeepInfraClient"
    }

    async fn chat_completion(
        &self,
        prompt: &str,
        config: &ModelConfiguration,
    ) -> Result<InferenceResult, ModelError> {
        let url = "https://api.deepinfra.com/v1/openai/chat/completions";

        // Request body
        let body = serde_json::json!({
            "model": config.model_id,
            "messages": [
                { "role": "user", "content": prompt }
            ],
            "temperature": config.temperature.unwrap_or(0.7),
            "max_tokens": config.max_tokens.unwrap_or(1024),
        });

        let response = self.client.post(url)
            .header("Authorization", format!("Bearer {}", self.api_key))
            .header("Content-Type", "application/json")
            .json(&body)
            .send()
            .await
            .map_err(|e| ModelError::Network(e.to_string()))?;

        let status = response.status();
        if !status.is_success() {
            let error_text = response.text().await.unwrap_or_else(|_| "Unknown error".to_string());
            return Err(ModelError::Api(format!("Status {}: {}", status, error_text)));
        }

        let json: serde_json::Value = response.json().await
            .map_err(|e| ModelError::Network(format!("Failed to parse JSON: {}", e)))?;

        let content = json["choices"][0]["message"]["content"]
            .as_str()
            .unwrap_or("")
            .to_string();

        let usage = json.get("usage").and_then(|u| {
            let prompt = u["prompt_tokens"].as_u64().map(|x| x as u32);
            let completion = u["completion_tokens"].as_u64().map(|x| x as u32);
            let total = u["total_tokens"].as_u64().map(|x| x as u32);
            Some(TokenUsage {
                prompt_tokens: prompt.unwrap_or(0),
                completion_tokens: completion.unwrap_or(0),
                total_tokens: total.unwrap_or(0),
            })
        });

        Ok(InferenceResult { content, usage })
    }
}
